contract InvMutTest {
    C c;
    uint public calls;
    address public lastFrom;
    address public lastTo;
    uint public lastV;

    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory tos, uint v) public {
        require(tos.length > 0);
        bool r = c.transfer(from, caddress, tos, v);
        assert(r && calls == tos.length && lastFrom == from && lastTo == tos[tos.length - 1] && lastV == v);
    }

    fallback() external {
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        if (bytes4(msg.data) == id) {
            (address f, address t, uint a) = abi.decode(msg.data[4:], (address, address, uint256));
            calls++;
            lastFrom = f;
            lastTo = t;
            lastV = a;
        }
    }

    receive() external payable {}
}

